1	use camino::{Utf8Path, Utf8PathBuf};
2	use ignore::gitignore::{Gitignore, GitignoreBuilder};
3	
4	use crate::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
5	
6	/// Walk `src_dirs` and collect every TypeScript file (`.ts`, `.tsx`, `.mts`, `.cts`), excluding:
7	/// - Built-in patterns: `.stories.`, `.test.`, `.spec.`, `__snapshots__`, `node_modules`
8	/// - User-supplied extra exclude patterns: gitignore-style globs on the path inside the source directory (see
9	///   [`compile_excludes`]); one that does not parse excludes nothing and is reported
10	///
11	/// Returns discovered files alongside any diagnostics raised while walking
12	/// (e.g. a permission-denied subtree) — never dropped silently (AGENTS.md
13	/// non-negotiable #6).
14	pub(super) fn discover_files(
15	    src_dirs: &[Utf8PathBuf],
16	    extra_excludes: &[String],
17	) -> (Vec<Utf8PathBuf>, Vec<Diagnostic>) {
18	    let (extra_excludes, invalid) = compile_excludes(extra_excludes);
19	    let extra_excludes = &extra_excludes;
20	    let found = std::sync::Mutex::new((Vec::new(), invalid_pattern_diagnostics(&invalid)));
21	
22	    for dir in src_dirs {
23	        // If the user explicitly points at a node_modules path, respect it.
24	        let dir_is_in_node_modules = in_node_modules(dir);
25	
26	        // Walking from the canonical root makes every entry's path canonical except a symlink itself (the walker
27	        // doesn't follow symlinked directories), so only those pay for `canonicalize` below.
28	        let root = crate::canonical_path::canonicalize(dir).unwrap_or_else(|_| dir.clone());
29	        let walker = ignore::WalkBuilder::new(root.as_std_path())
30	            .hidden(false)
31	            .git_ignore(!dir_is_in_node_modules)
32	            .build_parallel();
33	        walker.run(|| {
34	            let (found, root) = (&found, &root);
35	            Box::new(move |result| {
36	                let visited = visit(result, dir, root, dir_is_in_node_modules, extra_excludes);
37	                if let Some(visited) = visited {
38	                    let mut found = found.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
39	                    match visited {
40	                        Ok(file) => found.0.push(file),
41	                        Err(diagnostic) => found.1.push(diagnostic),
42	                    }
43	                }
44	                ignore::WalkState::Continue
45	            })
46	        });
47	    }
48	
49	    let (mut files, mut diagnostics) = found.into_inner().unwrap_or_else(|poisoned| poisoned.into_inner());
50	    // Sort for deterministic ordering across OS/FS and walker threads, then dedup: overlapping src_dirs (e.g.
51	    // ["./src", "./src/components"]) walk the same physical file more than once, and since paths are canonical, an
52	    // exact duplicate always sorts adjacent.
53	    files.sort();
54	    files.dedup();
55	    diagnostics.sort_by(|a, b| a.message.cmp(&b.message));
56	    (files, diagnostics)
57	}
58	
59	/// Every directory `discover_files` walks under `src_dirs` (canonical), and every file in them named `is_config`: a
60	/// file created in or deleted from one of these directories changes the directory's modification time.
61	pub(super) fn discover_dirs(
62	    src_dirs: &[Utf8PathBuf],
63	    extra_excludes: &[String],
64	    is_config: impl Fn(&str) -> bool,
65	) -> (Vec<Utf8PathBuf>, Vec<Utf8PathBuf>) {
66	    let (extra_excludes, _) = compile_excludes(extra_excludes);
67	    let extra_excludes = &extra_excludes;
68	    let (mut dirs, mut configs) = (Vec::new(), Vec::new());
69	    for dir in src_dirs {
70	        let dir_is_in_node_modules = in_node_modules(dir);
71	        let root = crate::canonical_path::canonicalize(dir).unwrap_or_else(|_| dir.clone());
72	        let walker =
73	            ignore::WalkBuilder::new(root.as_std_path()).hidden(false).git_ignore(!dir_is_in_node_modules).build();
74	        for entry in walker.flatten() {
75	            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path().to_owned()) else { continue };
76	            let relative = path.strip_prefix(&root).unwrap_or(&path);
77	            if excluded(relative.as_std_path(), dir_is_in_node_modules, extra_excludes) {
78	                continue;
79	            }
80	            if entry.file_type().is_some_and(|kind| kind.is_dir()) {
81	                dirs.push(path);
82	            } else if path.file_name().is_some_and(&is_config) {
83	                configs.push(path);
84	            }
85	        }
86	    }
87	    dirs.sort();
88	    dirs.dedup();
89	    configs.sort();
90	    configs.dedup();
91	    (dirs, configs)
92	}
93	
94	/// One walked entry: a source file to keep, a diagnostic, or `None` to skip it.
95	fn visit(
96	    result: Result<ignore::DirEntry, ignore::Error>,
97	    dir: &Utf8Path,
98	    root: &Utf8Path,
99	    dir_is_in_node_modules: bool,
100	    extra_excludes: &Gitignore,
101	) -> Option<Result<Utf8PathBuf, Diagnostic>> {
102	    let entry = match result {
103	        Ok(entry) => entry,
104	        Err(err) => {
105	            return Some(Err(Diagnostic::new(
106	                DiagnosticSeverity::Warning,
107	                DiagnosticCode::IoError,
108	                format!("Error walking '{dir}': {err}"),
109	            )
110	            .with_file(dir.to_string())
111	            .with_help("Check file/directory permissions and for broken symlinks under this path.")));
112	        }
113	    };
114	    let path = entry.path();
115	    if !crate::extractor::is_typescript(path) {
116	        return None;
117	    }
118	    let relative = path.strip_prefix(root.as_std_path()).unwrap_or(path);
119	    if excluded(relative, dir_is_in_node_modules, extra_excludes) {
120	        return None;
121	    }
122	    match Utf8PathBuf::from_path_buf(path.to_owned()) {
123	        // Absolute and canonical, so parent.fileName in output is stable regardless of invocation context (relative
124	        // --src, absolute --src, cwd inside the src dir). A dangling symlink keeps its own path rather than being
125	        // dropped.
126	        Ok(utf8) if entry.path_is_symlink() => Some(Ok(crate::canonical_path::canonicalize(&utf8).unwrap_or(utf8))),
127	        Ok(utf8) => Some(Ok(utf8)),
128	        Err(_) => Some(Err(Diagnostic::new(
129	            DiagnosticSeverity::Warning,
130	            DiagnosticCode::IoError,
131	            format!("Skipping non-UTF8 path: {}", path.to_string_lossy()),
132	        )
133	        .with_help("Rename the file to use valid UTF-8 characters in its path."))),
134	    }
135	}
136	
137	/// Whether `dir` is a `node_modules` directory or inside one: a path component, not text, so `~/node_modules-backup/`
138	/// is not.
139	fn in_node_modules(dir: &Utf8Path) -> bool {
140	    dir.components().any(|component| component.as_str() == "node_modules")
141	}
142	
143	/// Excludes apply to the path inside the source directory: a project checked out under `my.test.repo/` or
144	/// `~/node_modules-backup/` must not lose every file. `node_modules` is skipped only when the source directory is not
145	/// itself inside one.
146	fn excluded(relative: &std::path::Path, dir_is_in_node_modules: bool, extra_excludes: &Gitignore) -> bool {
147	    let file_name = relative.file_name().and_then(|n| n.to_str()).unwrap_or("");
148	    let in_component = |name: &str| relative.components().any(|c| c.as_os_str() == name);
149	    file_name.contains(".stories.")
150	        || file_name.contains(".test.")
151	        || file_name.contains(".spec.")
152	        || in_component("__snapshots__")
153	        || (!dir_is_in_node_modules && in_component("node_modules"))
154	        || extra_excludes.matched_path_or_any_parents(relative, false).is_ignore()
155	}
156	
157	/// The user's `exclude` patterns as one matcher over paths relative to a source directory. Patterns are gitignore-style
158	/// globs: `*.tsx`, `legacy/` (a directory), `**/fixtures/**`, `src/Button.tsx` (anchored at the source directory, as it
159	/// has a slash). A bare name such as `Button` matches only a file or directory named exactly that. The patterns that do
160	/// not parse come back beside the matcher and match nothing.
161	pub(super) fn compile_excludes(patterns: &[String]) -> (Gitignore, Vec<(String, ignore::Error)>) {
162	    let mut builder = GitignoreBuilder::new("");
163	    let mut invalid: Vec<(String, ignore::Error)> = patterns
164	        .iter()
165	        .filter_map(|pattern| builder.add_line(None, pattern).err().map(|err| (pattern.clone(), err)))
166	        .collect();
167	    let matcher = builder.build().unwrap_or_else(|err| {
168	        invalid.push((patterns.join(", "), err));
169	        Gitignore::empty()
170	    });
171	    (matcher, invalid)
172	}
173	
174	fn invalid_pattern_diagnostics(invalid: &[(String, ignore::Error)]) -> Vec<Diagnostic> {
175	    invalid
176	        .iter()
177	        .map(|(pattern, err)| {
178	            Diagnostic::new(
179	                DiagnosticSeverity::Warning,
180	                DiagnosticCode::IoError,
181	                format!("exclude pattern '{pattern}' is not a valid glob and excludes nothing: {err}"),
182	            )
183	            .with_help("Exclude patterns are gitignore-style globs, e.g. \"**/*.fixture.tsx\" or \"legacy/\".")
184	        })
185	        .collect()
186	}
187	
188	/// Whether discovery would include `path`: TypeScript, under a source directory, and not excluded. Watch mode asks
189	/// this of every changed path so an edit to an excluded file (a story, a test) never adds a component.
190	pub(super) fn is_source_file(path: &Utf8Path, src_dirs: &[Utf8PathBuf], extra_excludes: &[String]) -> bool {
191	    if !crate::extractor::is_typescript(path.as_std_path()) {
192	        return false;
193	    }
194	    let (extra_excludes, _) = compile_excludes(extra_excludes);
195	    src_dirs.iter().any(|dir| {
196	        let dir = crate::canonical_path::canonicalize(dir).unwrap_or_else(|_| dir.clone());
197	        path.strip_prefix(&dir)
198	            .is_ok_and(|relative| !excluded(relative.as_std_path(), in_node_modules(&dir), &extra_excludes))
199	    })
200	}
201	
202	pub(super) fn should_skip(name: &str, exclude_prefixes: &[String]) -> bool {
203	    exclude_prefixes.iter().any(|p| name.starts_with(p.as_str()))
204	}
