30	            .hidden(false)
31	            .git_ignore(!dir_is_in_node_modules)
32	            .build_parallel();
33	        walker.run(|| {
34	            let (found, root) = (&found, &root);
35	            Box::new(move |result| {
36	                let visited = visit(result, dir, root, dir_is_in_node_modules, extra_excludes);
37	                if let Some(visited) = visited {
38	                    let mut found = found.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
39	                    match visited {
40	                        Ok(file) => found.0.push(file),
41	                        Err(diagnostic) => found.1.push(diagnostic),
42	                    }
43	                }
44	                ignore::WalkState::Continue
45	            })
46	        });
